/**
 * Image slots. Each slot is designed for one placement (owner's image system,
 * 2026-11-19). Files are AI-generated by Clynera Tech and imported from
 * `images-inbox/` with `npm run media:import`, which writes
 * public/images/<folder>/<file>.webp. Until a file exists, <Visual> renders
 * original procedural art in the same composition, so no slot is ever empty.
 *
 * `people: true` marks realistic human subjects: they always show an
 * "Illustration" tag so no one mistakes them for Clynera staff.
 */
export type Tone = "dark" | "light";
/** Where the visual weight sits; the rest of the frame stays quiet for type. */
export type Weight = "right" | "left" | "bottom" | "center" | "band";

export type VisualSlot = {
  file: string;
  folder: string;
  ratio: [number, number];
  tone: Tone;
  weight: Weight;
  alt: string;
  people?: boolean;
};

const slot = (file: string, folder: string, ratio: [number, number], tone: Tone, weight: Weight, alt: string, people = false): VisualSlot => ({
  file,
  folder,
  ratio,
  tone,
  weight,
  alt,
  people,
});

